import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'data'
def read(c):return json.loads((p/(c+'.json')).read_text())
def write(c,d):(p/(c+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2))
def enrich(c,name,url,key,fields,date='05.11.2013 — дата публикации, дата редакции неизвестна',version='браузерная игра ВКонтакте, исторический фанатский каталог'):
 d=read(c);e=next((a for a in d if a['name']==name),None)
 if not e: print('не найдено:',c,name);return
 e.setdefault('prior_records',[]);e['prior_records']=[r for r in e['prior_records'] if r.get('original_id')!=key]+[{'original_id':key,'original_category':'Прочитанная статья','version':version,'date':date,'fields':fields,'confidence':'Исторический фанатский источник, условия могут различаться между версиями и редакциями.'}]
 if not any(s['url']==url for s in e['sources']):e['sources'].append({'url':url,'label':'Прочитанная страница'})
 write(c,d)
base='https://zombi.at.ua/board/materialy/piraty/'
enrich('materials','Пиратский сундук',base+'piratskij_sunduk/31-1-0-956','pirate-source-956',{'Получение':'Выиграть в Таверне; купить и подарить нельзя.','Применение':'Для пирата — собрать инструменты для путешествия, для горожанина — возможность ограбить пирата, найдя сундук. Вместимость 80 единиц.'})
enrich('materials','Дублон',base+'dublon/31-1-0-955','pirate-source-955',{'Получение':'Обмен коллекции Палача, выигрыш в Таверне, задание «Отшельник»; также покупка за голоса.','Исторические цены':'25 за 5 голосов, 100 за 18 голосов, 1000 за 150 голосов. Не считать актуальными.','Применение':'Рулетка в Таверне и корабль для путешествия.'})
for name,slug,num,use in [('Кирка','kirka','954','Расчистка камней'),('Мачете','machete','953','Вырубка кустов'),('Топор','topor','952','Вырубка деревьев')]:
 fields={'Использование':use+' на пиратских островах; купить и продать по таблице нельзя.','Получение':'Рулетки «Бочка фортуны», «Колодец желаний», «Пиратская рулетка»; задания «За облаками», «Таверна».'}
 if name=='Кирка':fields['Оговорка']='В строке получения кирки исходная страница ошибочно пишет «Топор можно выиграть», поэтому принадлежность списка кирке требует сверки.'
 enrich('materials',name,base+slug+'/31-1-0-'+num,'pirate-source-'+num,fields)
for name,slug,num,collections in [('Чаша','chasha','961','Тинейджерская, Пляжная и Игрушек'),('Череп','cherep','960','Тропическая, Плохая и Изумрудная'),('Шкатулка','shkatulka','959','Палача, Тропическая и Плохая'),('Ваза','vaza','957','Щенков, Котят и Пляжная'),('Бутылка','butylka','962','Плохая и Тропическая')]:
 enrich('materials',name,base+slug+'/31-1-0-'+num,'pirate-source-'+num,{'Получение':'На пиратских островах; купить и подарить нельзя по исторической таблице.','При открытии':'На странице сказано, что после открытия дома можно получить коллекции: '+collections+'. Формулировка источника не уточняет размер награды или вероятность; не следует считать все перечисленные коллекции гарантированными.'})
base2='https://zombi.at.ua/board/materialy/cirkovye_materialy/'
for n,slug,num,fields in [('Простыня','prostynja','930',{'Получение':'В Кино: 5 предметов по файлу shelk.png и 10 по файлу kraska_belaya.jpg; предположительно шёлк и белая краска, иконки необходимо сверить.','Использование':'Строительство Кино и Планетария; стоимость по лимиту 1000 монет.'}),('Лунный камень','lunnyj_kamen','932',{'Получение':'Могут привезти туристы.','Использование':'Строительство Планетария.'}),('Бозон Хиггса','bozon_khiggsa','934',{'Получение':'Под Перроном, в праздничных рулетках, в Фемиде в подарке с жёлтой лентой, в Коллайдере. Предмет нельзя дарить.','Оговорка об акции':'Под изображением Перрона сказано, что его можно было получить только на акции 22–23 августа; год не указан, дата публикации страницы не доказывает год акции.'})]:enrich('materials',n,base2+slug+'/30-1-0-'+num,'circus-verified-'+num,fields,'02–03.08.2013 — дата публикации; редакция неизвестна')
