for name,text in [('Мыло','Под сакурой в горшке.'),('Газеты','Под зимними декорациями, ледяными глыбами, ковром-самолётом.'),('Кафель','Под бизнес-центром и Белым домом.')]:enrich('materials',name,u,'zommbie-dig-'+name,{'Где копать':text},'10.01.2014 — дата публикации','браузерная социальная версия; сеть не уточнена')
s=read('sources')
for x in s:
 if x['number']==14:x['summary']+=' Прочитана статья от 10.01.2014 о раскопках: текст списка коллекций совпадает с Зомбастиками; не считать независимым подтверждением.'
 if x['number']==9:x['summary']+=' Списки коллекций совпадают с Zommbie.at.ua, направление заимствования неизвестно.'
 if x['number']==10:x['summary']+=' Прочитаны «Секреты игры»: экономический пример красной краски и советы по весенней коллекции для Мой Мир.'
